import time

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(func):
        cache = {}
        hits = misses = 0

        def outer_wrapper(*args, **kwargs):
            key = args + kwargs if not typed else (args, kwargs)
            if key in cache:
                hits += 1
                ts, result = cache[key]
                if timer() - ts > ttl:
                    del cache[key]
                    return outer_wrapper(*args, **kwargs)
                return result
            result = func(*args, **kwargs)
            cache[key] = (timer(), result)
            misses += 1
            if len(cache) > maxsize:
                cache.popitem(last=False)
            return result

        outer_wrapper.cache_info = lambda : (hits, misses, len(cache))
        return outer_wrapper

    return decorator
