def lru_cache(maxsize=128, typed=False):
    def wrapper(f):
        cache = dict()
        def inner(*args, **kwargs):
            if typed:
                k = (args, tuple(kwargs.items()))
            else:
                k = (args, tuple(kwargs.items()), hash(f))
            if k not in cache:
                cache[k] = f(*args, **kwargs)
            else:
                cache[k] = _ = cache[k]
            return _
        return inner
    return wrapper
