def format(sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    if isinstance(params, Mapping):
        formatted_sql, out_params = _format_mapped_params(sql, params)
    elif isinstance(params, Sequence):
        formatted_sql, out_params = _format_sequenced_params(sql, params)
    else:
        raise ValueError("params must be a dict or a sequence")
    return formatted_sql, out_params

def _format_mapped_params(sql: AnyStr, params: Dict[Union[str, int], Any]) -> Tuple[AnyStr, Dict[Union[str, int], Any]]:
    out_params = {}
    for name, value in params.items():
        if value is None:
            out_params[name] = 'NULL'
        else:
            out_params[name] = repr(value)
    return sql.format(**out_params), out_params

def _format_sequenced_params(sql: AnyStr, params: Sequence[Any]) -> Tuple[AnyStr, List[Any]]:
    num_params = len(params)
    if num_params == 0:
        return sql, []
    out_params = [repr(param) for param in params]
    for i in range(num_params):
        sql = sql.replace('$' + str(i + 1), '{}')
    return sql.format(*out_params), out_params
