def check_hierarchy(folder, validate_objects=True, check_digests=True, show_warnings=False):
    if not os.path.exists(folder):
        if show_warnings:
            print(f"Warning: Folder '{folder}' does not exist")
        return 0

    num_objects = 0
    good_objects = 0

    for obj in folder.get_objects():
        num_objects += 1
        if not obj.object_id:
            if validate_objects:
                if show_warnings:
                    print(f"Error: Object '{obj.name}' missing object id")
                continue
        if not obj.digest:
            if check_digests:
                if show_warnings:
                    print(f"Error: Object '{obj.name}' missing digest")
                continue
        if validate_objects:
            if not obj.is_valid():
                if show_warnings:
                    print(f"Error: Object '{obj.name}' failed validation")
                continue
            else:
                good_objects += 1

    return num_objects, good_objects
