def parse_value(value):
    if value.lower() == "false":
        return False
    if value.lower() == "true":
        return True
    if value.startswith("{"):
        return parse_dict(value)
    if value.startswith("["):
        return parse_list(value)
    try:
        return parse_float(value)
    except ValueError:
        return parse_int(value)
