def dict_insert(dic: Dict[str, Any], val: Any, key: str, *keys: List[str]) -> Dict[str, Any]:
    if not keys:
        dic[key] = val
        return dic

    if key not in dic:
        dic[key] = {}

    return dict_insert(dic[key], val, *keys)
```

